.board-viewport {
  --card-min: 44px;
  --card-max: 88px;
  --card-gap: 6px;
  --board-padding: 6px;
  --board-border: 1px;
  max-height: min(70dvh, 768px);
  overflow: auto;
  overscroll-behavior: contain;
  padding: var(--board-padding);
  border: var(--board-border) solid var(--border);
  border-radius: 12px;
  background: var(--panel);
  width: fit-content;
  max-width: 100%;
}
.board {
  display: grid;
  gap: var(--card-gap);
  grid-template-columns: repeat(var(--grid-size), minmax(var(--card-min), var(--card-max)));
  /* The scroll area's content box already leaves room for page and board scrollbars. */
  width: clamp(
    calc(var(--grid-size) * var(--card-min) + (var(--grid-size) - 1) * var(--card-gap)),
    100%,
    calc(var(--grid-size) * var(--card-max) + (var(--grid-size) - 1) * var(--card-gap))
  );
}
:root {
  font-family: system-ui, sans-serif;
  font-size: 16px;
  line-height: 24px;
  color: #f4f6ff;
  background: #090b14;
  color-scheme: dark;
  --text: #f4f6ff;
  --secondary: #b8bdd2;
  --panel: #141827;
  --back: #1b2034;
  --face: #111625;
  --border: #757c9a;
  --green: #8bea7d;
  --content-max: 1120px;
  --page-padding: 16px;
}
* {
  box-sizing: border-box;
}
body {
  margin: 0;
}
main {
  width: 100%;
  max-width: var(--content-max);
  margin: 0 auto;
  padding: var(--page-padding);
}
header {
  margin: 4px 0 12px;
}
h1 {
  font-size: 24px;
  line-height: 32px;
  margin: 4px 0;
}
p {
  margin: 0;
}
.eyebrow {
  color: var(--secondary);
  font-size: 14px;
}
.intro {
  font-size: 14px;
  color: var(--secondary);
  margin-bottom: 24px;
}
.help {
  color: var(--secondary);
  font-size: 14px;
  max-width: 70ch;
  margin-bottom: 12px;
}
:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}
.game-result {
  display: flex;
  align-items: center;
  min-height: 56px;
  margin: 4px 0 8px;
}
